package com.mis.mis_backend.examination;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/examinations") public class ExaminationController{private final ExaminationService s;public ExaminationController(ExaminationService s){this.s=s;}@GetMapping public List<Examination> getAll(){return s.getAll();}@PostMapping public Examination create(@RequestBody Examination x){return s.create(x);}}